#include <map>
#include <algorithm>
#include <iostream>

int main() {
    std::map<int, std::string> m = {{1, "Apple"}, {2, "Banana"}};

    // O(log N) Key Search (Efficient)
    auto it_key = m.find(1);

    // O(N) Value Search (Inefficient)
    auto it_val = std::find_if(
        m.begin(), m.end(), 
        [](const auto& pair) { 
            return pair.second == "Banana"; 
        }
    );

    if (it_val != m.end()) {
        std::cout << "Found key: " << it_val->first << " (O(N))\n";
    }
}
